    int n ;
    cin >> n;
    vector<int> ans(n);
    // 所有得分
    int sum = 0;
    for (int i = 0; i < n; i++) {
        cin >> ans[i];
        sum += ans[i];
    }
    // 将分数进行逆序排序
    sort(ans.begin(), ans.end(), cmp);
    // 从大到小枚举获取MVP的人数， 大小范围为 1 - m
    while (n != 1) {
        if (canPartition(ans, n, sum)) {
            break;
        }
        n--;
    }
    cout << sum / n;
    return 0;
}

