import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;
​
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
​
        int m = sc.nextInt();
        int sum = 0;
        List<Integer> link = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int tmp = sc.nextInt();
            link.add(tmp);
            sum += tmp;
        }
​
        System.out.println(getResult(link, m, sum));
    }
​
    public static int getResult(List<Integer> link, int m, int sum) {
        // 将分数逆序排序
        link.sort((a, b) -> b - a);
        // 从 m - 1 枚举可能存在MVP人数
        while (m >= 1) {
            if (canPartitionMSubsets(link, sum, m)) return sum / m;
            m--;
        }
​
        return sum;
    }
​
    public static boolean canPartitionMSubsets(List<Integer> link, int sum, int m) {
        if (sum % m != 0) return false;
​
        int subSum = sum / m;
        // 分数不可拆分，肯定不满足条件
        if (subSum < link.get(0)) return false;
        int size = link.size();
        // 第一个小于subSum分数的位置
        int beginIndex = 0;
        while (beginIndex < size && link.get(beginIndex) == subSum) {
            beginIndex++;
            m--;
        }
​
        int[] buckets = new int[m];
        return partition(link, beginIndex, buckets, subSum);
    }
​
    public static boolean partition(List<Integer> link, int index, int[] buckets, int subSum) {
        if (index == link.size()) return true;
​
        int select = link.get(index);
​
        for (int i = 0; i < buckets.length; i++) {
            // 剪枝，各个堆是对等的，前一个不成立那么当前也会成立。 剪枝
            if (i > 0 && buckets[i] == buckets[i - 1]) continue;
            if (select + buckets[i] <= subSum) {
                buckets[i] += select;
                if (partition(link, index + 1, buckets, subSum)) return true;
                buckets[i] -= select;
            }
        }
​
        return false;
    }
}

